(()=>{
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const isEn=()=>document.querySelector('lri-site-shell')?.locale==='en'||document.documentElement.lang.toLowerCase().startsWith('en');
  const L=(zh,en)=>isEn()?en:zh;
  const pick=(obj,key)=>isEn()&&obj?.[`${key}_en`]!=null?obj[`${key}_en`]:obj?.[key];
  const pickReader=(reader,snapshot,key='statement')=>isEn()?(reader?.[`${key}_en`]??snapshot?.[`${key}_en`]??reader?.[key]??snapshot?.[key]):(reader?.[key]??snapshot?.[key]);
  const metricLabel=m=>isEn()?(m?.label_en||m?.label||''):(m?.label||'');
  const normalizeMetrics=value=>Array.isArray(value)?value:(value&&typeof value==='object'?Object.entries(value).map(([key,metricValue])=>({label:key.replaceAll('_',' '),value:metricValue})):[]);
  let cfg=null,registry=null,modal=null,bound=false,currentSignalId=null;
  const dictionaries=new Map();
  const ensureModal=()=>{if(modal)return modal;const host=document.createElement('div');host.className='lri-signal-modal-root';host.innerHTML=`<div class="lri-signal-backdrop" data-signal-close></div><section class="lri-signal-modal" role="dialog" aria-modal="true" aria-labelledby="lri-signal-title"><button class="lri-signal-close" type="button" aria-label="${esc(L('关闭','Close'))}" data-signal-close>×</button><div class="lri-signal-scroll"><div class="lri-signal-loading">${esc(L('加载中…','Loading…'))}</div></div></section>`;document.body.appendChild(host);modal=host;host.addEventListener('click',e=>{if(e.target.closest('[data-signal-close]'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&host.classList.contains('open'))close()});return host};
  const close=()=>{currentSignalId=null;if(modal){modal.classList.remove('open');document.documentElement.classList.remove('lri-signal-modal-open')}};
  const loadJson=async url=>{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);return r.json()};
  const loadRegistry=async()=>registry||(registry=await loadJson(cfg.registryUrl));
  const loadDictionary=async uri=>{const url=new URL(uri,cfg.insightRoot).href;if(!dictionaries.has(url))dictionaries.set(url,loadJson(url));return dictionaries.get(url)};
  const fullVisual=input=>{const d=globalThis.LRISignalVisual?.materialize(input,'compact_card')||input;const snap=d.snapshot||{},reader=d.reader||{},metrics=normalizeMetrics(reader.metrics??snap.metrics).slice(0,3),why=(d.why_it_matters||[]).slice(0,3),bounds=(d.boundaries||[]).slice(0,2),judgments=(d.supported_judgments||[]).slice(0,2),lang=isEn()?'en':'zh';const theories=(d.theory_refs||[]).length?`<div class="lri-signal-theory"><span>${esc(L('理论底座','Theory foundation'))}</span>${d.theory_refs.map(id=>`<button type="button" data-theory-id="${esc(id)}">${esc(L('查看理论解释','Open theory explanation'))}</button>`).join('')}</div>`:'';const archetype=d.__visual?.archetype||d.visual_grammar?.archetype||'generic',am=globalThis.LRISignalVisualPrimitives?.meta(archetype,lang)||{label:L('机制','Mechanism'),accent:'#3569a8',soft:'#edf5fd'},mechanismVisual=globalThis.LRISignalVisualPrimitives?.mechanismSvg(d,{mode:'compact',lang})||'',takeaway=pick(d,'one_line_takeaway');return `<div class="lri-signal-sheet lri-signal-full" data-archetype="${esc(archetype)}" style="--signal-accent:${esc(am.accent)};--signal-soft:${esc(am.soft)}"><header class="lri-signal-hero"><div class="lri-signal-hero-copy"><div class="lri-signal-kicker">SIGNAL INSIGHT · VERIFIED <span class="lri-signal-archetype">${esc(am.label)}</span></div><h2 id="lri-signal-title">${esc(pick(d,'title'))}</h2><p>${esc(pick(d,'subtitle')||'')}</p></div><div class="lri-signal-hero-meta"><span>${esc(snap.event_date||'')}</span><span>${esc(pick(snap,'evidence_level')||'')}</span><span>${esc(pick(snap,'maturity')||'')}</span></div>${takeaway?`<div class="lri-signal-takeaway">${esc(takeaway)}</div>`:''}</header><section class="lri-signal-snapshot compact"><div class="lri-signal-fact"><span>${esc(L('FACT · 事实锚点','FACT · Evidence anchor'))}</span><p>${esc(pickReader(reader,snap))}</p></div><div class="lri-signal-metrics">${metrics.map(m=>`<article><strong>${esc(pick(m,'value'))}</strong><span>${esc(metricLabel(m))}</span></article>`).join('')}</div></section><section class="lri-signal-main-grid"><article class="lri-signal-panel why"><h3>${esc(L('WHY · 为什么重要','WHY · Why it matters'))}</h3>${why.map((x,i)=>`<div class="lri-signal-point"><span>${i+1}</span><div><b>${esc(pick(x,'title'))}</b><p>${esc(pick(x,'body'))}</p></div></div>`).join('')}</article><article class="lri-signal-panel mechanism"><h3>${esc(L('MECHANISM · 技术机制','MECHANISM · Technical mechanism'))}</h3><p class="lri-signal-mech-head">${esc(pick(d.mechanism,'headline')||'')}</p><div class="lri-signal-mechanism-visual">${mechanismVisual}</div></article><article class="lri-signal-panel inference"><div class="lri-inference-block"><h3>${esc(L('JUDGMENT · 支持判断','JUDGMENT · Supported judgment'))}</h3><ul>${judgments.map(x=>`<li>${esc(pick(x,'statement'))}</li>`).join('')}</ul></div><div class="lri-inference-block boundary"><h3>${esc(L('BOUNDARY · 证据边界','BOUNDARY · Evidence boundary'))}</h3><ul>${bounds.map(x=>`<li>${esc(typeof x==='string'?x:pick(x,'text'))}</li>`).join('')}</ul></div></article></section>${theories}</div>`};
  const compactVisual=d=>{const snap=d.snapshot||{},reader=d.reader||{},metrics=normalizeMetrics(reader.metrics??snap.metrics).slice(0,4),src=d.source_context||{},rels=(d.relations||[]).slice(0,3),topic=d.topic||{},entities=d.entities||[],score=[d.evidence_strength!=null?`${L('证据','Evidence')} ${d.evidence_strength}/5`:null,d.impact!=null?`${L('影响','Impact')} ${d.impact}/5`:null,d.strategic_relevance!=null?`${L('战略相关','Strategic relevance')} ${d.strategic_relevance}/5`:null].filter(Boolean);const relationHtml=rels.length?rels.map(r=>{const trend=isEn()?r.trend_name_en:r.trend_name,claim=isEn()?r.claim_statement_en:r.claim_statement,reason=isEn()?r.reason_en:r.reason;return `<div class="lri-compact-relation"><div><span class="stance ${esc(r.stance||'neutral')}">${esc(r.stance||'related')}</span>${r.strength!=null?`<span class="strength">${esc(r.strength)}/5</span>`:''}</div>${trend?`<b>${esc(trend)}</b>`:''}${claim?`<p>${esc(claim)}</p>`:''}${reason?`<small>${esc(reason)}</small>`:''}</div>`}).join(''):`<div class="lri-compact-empty">${esc(L('当前 Dictionary Projection 未投影 Claim / Trend 关系；该 Signal 仍保留为独立已验证事实。','No Claim / Trend relation is projected for this Signal; it remains an independently verified fact.'))}</div>`;const subtitle=isEn()?(d.subtitle_en||topic.name_en||d.signal_type||''):(d.subtitle||topic.name_zh||d.signal_type||''),sourceName=isEn()?(reader.source_name_en||src.name_en||src.name||L('已验证来源','Verified source')):(reader.source_name||src.name||'已验证来源'),policy=isEn()?(d.projection_policy?.note_en||'Compact Insight projects Authority data only and does not synthesize inference.'):(d.projection_policy?.note_zh||'Compact Insight 仅投影 Authority 数据，不自动生成推断。');return `<div class="lri-signal-sheet lri-signal-compact-only"><header class="lri-signal-hero compact-hero"><div class="lri-signal-hero-copy"><div class="lri-signal-kicker">SIGNAL DICTIONARY · VERIFIED <span class="lri-signal-archetype">Compact</span></div><h2 id="lri-signal-title">${esc(pick(d,'title')||d.title)}</h2><p>${esc(subtitle)}</p></div><div class="lri-signal-hero-meta"><span>${esc(snap.event_date||'')}</span>${d.signal_type?`<span>${esc(d.signal_type)}</span>`:''}${snap.evidence_level?`<span>${esc(pick(snap,'evidence_level'))}</span>`:''}</div></header><section class="lri-signal-snapshot compact lri-compact-snapshot"><div class="lri-signal-fact"><span>${esc(L('FACT · 原子事实','FACT · Atomic fact'))}</span><p>${esc(pickReader(reader,snap))}</p></div>${metrics.length?`<div class="lri-signal-metrics compact-metrics">${metrics.map(m=>`<article><strong>${esc(pick(m,'value'))}</strong><span>${esc(metricLabel(m))}</span></article>`).join('')}</div>`:''}</section><section class="lri-compact-context"><article class="lri-signal-panel source-context"><h3>${esc(L('CONTEXT · 证据上下文','CONTEXT · Evidence context'))}</h3><div class="lri-compact-source"><b>${esc(src.organization||sourceName)}</b><p>${esc(sourceName)}</p></div><div class="lri-compact-chips">${topic.domain?`<span>${esc(topic.domain)}</span>`:''}${topic.name_zh||topic.name_en?`<span>${esc(isEn()?(topic.name_en||topic.name_zh):(topic.name_zh||topic.name_en))}</span>`:''}${entities.slice(0,4).map(x=>`<span>${esc(x)}</span>`).join('')}${score.map(x=>`<span>${esc(x)}</span>`).join('')}</div></article><article class="lri-signal-panel relation-context"><h3>${esc(L('GRAPH · 显式关系','GRAPH · Explicit relations'))}</h3>${relationHtml}</article></section><div class="lri-compact-policy">${esc(policy)}</div></div>`};
  const resolveItem=async item=>{if(item.insight_level==='full'&&item.data_uri){const d=await loadJson(new URL(item.data_uri,cfg.insightRoot).href);d.__insight_level='full';return d}const dict=await loadDictionary(item.dictionary_uri||'data/signal-dictionary.json');const d=dict.items?.[item.dictionary_key||item.signal_id];if(!d)throw new Error(L('Signal Dictionary 中未找到对应条目','Signal Dictionary entry not found'));return d};
  const open=async signalId=>{if(!cfg||!signalId)return;currentSignalId=signalId;const m=ensureModal(),scroll=m.querySelector('.lri-signal-scroll'),closeButton=m.querySelector('.lri-signal-close');m.classList.add('open');document.documentElement.classList.add('lri-signal-modal-open');if(closeButton)closeButton.setAttribute('aria-label',L('关闭','Close'));scroll.innerHTML=`<div class="lri-signal-loading">${esc(L('加载中…','Loading…'))}</div>`;try{const reg=await loadRegistry(),item=(reg.items||[]).find(x=>x.signal_id===signalId);if(!item)throw new Error(L('未找到对应 Signal Insight','Signal Insight not found'));const d=await resolveItem(item);const src=(d.sources||[]).find(x=>x.date===d.snapshot?.event_date)||(d.sources||[])[0];const isFull=item.insight_level==='full'&&item.data_uri;const detail=isFull?new URL(`${item.slug}/`,cfg.insightRoot).href:null;scroll.innerHTML=`${isFull?fullVisual(d):compactVisual(d)}<footer class="lri-signal-actions">${detail?`<a class="primary" href="${esc(detail)}">${esc(L('完整结构化洞察 →','Full structured insight →'))}</a>`:''}${src?.url?`<a${detail?'':' class="primary"'} href="${esc(src.url)}" target="_blank" rel="noreferrer">${esc(L('打开原始来源 ↗','Open raw source ↗'))}</a>`:''}</footer>`}catch(error){scroll.innerHTML=`<div class="lri-signal-error">${esc(L('视觉洞察暂不可用：','Visual insight unavailable: '))}${esc(error.message)}</div>`}};
  const configure=options=>{cfg={...options,insightRoot:new URL(options.insightRoot,location.href)};registry=null;dictionaries.clear();return api};
  const bind=(root=document)=>{if(bound)return api;bound=true;root.addEventListener('click',e=>{const el=e.target.closest('[data-signal-id]');if(!el)return;e.preventDefault();open(el.dataset.signalId)});return api};
  const api={configure,bind,open,close};globalThis.LRISignalModal=api;
  document.addEventListener('lri:locale-change',()=>{if(currentSignalId&&modal?.classList.contains('open'))open(currentSignalId)});
})();
